<?php
namespace App\Filament\Admin\Resources\PaymentRequests;use App\Domain\Tenancy\TenantContext;use App\Filament\Admin\Resources\PaymentRequests\Pages;use App\Models\PaymentIntentRecord;use BackedEnum;use Filament\Actions;use Filament\Resources\Resource;use Filament\Schemas\Schema;use Filament\Tables;use Filament\Tables\Table;use Illuminate\Database\Eloquent\Builder;
final class PaymentRequestResource extends \App\Filament\Shared\LocalizedResource{protected static?string$model=PaymentIntentRecord::class;protected static string|BackedEnum|null$navigationIcon='lucide-smartphone';protected static string|\UnitEnum|null$navigationGroup='Sales workspace';protected static?int$navigationSort=43;public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->where('tenant_id',app(TenantContext::class)->id());}public static function form(Schema$s):Schema{return$s->components([]);}
